import data from "@/lib/examples-data.json";

// P3 Examples, Templates and Components. Every figure and name on those three pages comes from examples-data.json, which
// is generated by running the real engine (`pnpm fixtures:examples`) and checked against it by a backend spec. This file
// only types that data and turns it into plain words; it computes no model results of its own.

export type GraphNode = { id: string; type: string; label: string; x: number; y: number; props: { region?: string } & Record<string, unknown> };
export type Graph = { nodes: GraphNode[]; edges: Array<{ id: string; from: string; to: string }> };
export type Traffic = { preset: string; rps: number; burst: number; readRatio: number; sloP95: number; errorBudget: number; durationMin: number; shape: string };
export type CurvePoint = { rps: number; p50: number; p95: number; p99: number; err: number; maxRho: number };
export type ExampleTemplate = {
  id: string;
  name: string;
  blurb: string;
  graph: Graph;
  traffic: Traffic;
  result: {
    p50: number;
    p95: number;
    p99: number;
    errorRate: number;
    verdict: "pass" | "strained" | "fail";
    sloMet: boolean;
    bottleneckId: string | null;
    bottleneckLabel: string | null;
    maxRho: number;
    nodes: Array<{ id: string; label: string; type: string; rho: number; status: string }>;
  };
  limits: {
    state: string;
    passingRps: number | null;
    failingRps: number | null;
    headroom: number | null;
    firstId: string | null;
    firstLabel: string | null;
    cause: "latency" | "errors" | "both" | null;
    order: Array<{ id: string; label: string; type: string; satRps: number | null }>;
    curve: CurvePoint[];
  };
};
export type CatalogComponent = {
  type: string;
  label: string;
  short: string;
  category: string;
  capacity: { kind: "finite"; value: number } | { kind: "unbounded" };
  latency: number;
  behavior: "none" | "shed" | "backlog" | "timeout" | "reject";
  blurb: string;
  defaults: { replicas: number; hitRatio?: number; share?: number; maxDepth?: number };
  editableProperties: string[];
};
export type Preset = { id: string; name: string; note: string; traffic: Traffic };
export type Catalog = { engineVersion: string; components: CatalogComponent[]; regions: Array<{ id: string; label: string }>; trafficDefaults: Traffic; presets: Preset[] };

const all = data as unknown as { engineVersion: string; templates: ExampleTemplate[]; catalog: Catalog };
export const TEMPLATES: ExampleTemplate[] = all.templates;
export const CATALOG: Catalog = all.catalog;
export const ENGINE_VERSION = all.engineVersion;
export const templateById = (id: string) => TEMPLATES.find((t) => t.id === id);

// ---------- formatting ----------

export const n0 = (x: number) => Math.round(x).toLocaleString("en-US");
export const pct = (x: number) => `${Math.round(x * 100).toLocaleString("en-US")}%`;
export const pct1 = (x: number) => `${(Math.round(x * 1000) / 10).toLocaleString("en-US")}%`;

// ---------- tags: worked out from the design itself, never typed by hand ----------

export type Tag = { id: string; label: string };
const BY_TYPE: Array<[string, string, string]> = [
  ["cache", "Has a cache", "cache"],
  ["queue", "Has a queue", "queue"],
  ["cdn", "Has a CDN", "cdn"],
  ["replicas", "Has read replicas", "replica"],
  ["storage", "Uses object storage", "storage"],
  ["external", "Calls an external service", "external"],
];
export const TAG_LIST: Tag[] = [...BY_TYPE.map(([id, label]) => ({ id, label })), { id: "regions", label: "Spans regions" }];

export function tagsOf(graph: Graph): Tag[] {
  const types = new Set(graph.nodes.map((n) => n.type));
  const regions = new Set(graph.nodes.map((n) => n.props.region ?? "us-east"));
  return TAG_LIST.filter((t) => (t.id === "regions" ? regions.size > 1 : types.has(BY_TYPE.find((b) => b[0] === t.id)![2])));
}

/** Only tags that apply to at least one template are offered, so a filter never leads to an empty list by design. */
export const tagsInUse = (templates: ExampleTemplate[] = TEMPLATES): Tag[] => {
  const used = new Set(templates.flatMap((t) => tagsOf(t.graph).map((g) => g.id)));
  return TAG_LIST.filter((t) => used.has(t.id));
};

/** A template matches when it has every selected tag. */
export const filterByTags = (templates: ExampleTemplate[], selected: readonly string[]) =>
  templates.filter((t) => {
    const have = new Set(tagsOf(t.graph).map((g) => g.id));
    return selected.every((id) => have.has(id));
  });

// ---------- plain words ----------

export const goalText = (t: Traffic) => `p95 at or under ${n0(t.sloP95)} ms and errors at or under ${pct1(t.errorBudget)}`;
const CAUSE: Record<string, string> = { latency: "latency: it gets too slow", errors: "errors: it starts dropping requests", both: "both latency and errors" };
export const causeWord = (cause: string | null) => (cause ? CAUSE[cause] : "no single cause");

export function breakingPointText(t: ExampleTemplate): string {
  const l = t.limits;
  if (l.state !== "found" || l.passingRps === null) return "The model did not find a single breaking point for this design.";
  const first = l.firstLabel ? `The first component to fail is ${l.firstLabel}, because of ${causeWord(l.cause)}.` : "";
  return `It holds its goal up to about ${n0(l.passingRps)} requests a second. ${first}`.trim();
}

export const VERDICT_WORD = { pass: "meets its goal", strained: "meets its goal but is close to the edge", fail: "misses its goal" } as const;

/** The design at the traffic it ships with, including the case where that traffic is already past its breaking point. */
export function ownResultText(t: ExampleTemplate): string {
  const r = t.result;
  const busiest = [...r.nodes].filter((n) => n.type !== "client").sort((a, b) => b.rho - a.rho)[0];
  const bottleneck = r.nodes.find((n) => n.id === r.bottleneckId);
  const strain = bottleneck ? `The busiest component is ${bottleneck.label} at ${pct(bottleneck.rho)} utilization.` : busiest ? `Nothing is under strain; the busiest component, ${busiest.label}, is ${pct(busiest.rho)} utilized.` : "";
  const past = t.limits.passingRps !== null && t.limits.passingRps < t.traffic.rps ? ` Its breaking point (about ${n0(t.limits.passingRps)} requests a second) is below the ${n0(t.traffic.rps)} it is tested at.` : "";
  return `At ${n0(t.traffic.rps)} requests a second it ${VERDICT_WORD[r.verdict]}: p95 ${n0(r.p95)} ms and ${pct1(r.errorRate)} errors, against a goal of ${goalText(t.traffic)}. ${strain}${past}`.replace(/\s+/g, " ").trim();
}

/** What the model says at one of the precomputed load levels. */
export function curveText(t: ExampleTemplate, index: number): string {
  const p = t.limits.curve[Math.max(0, Math.min(t.limits.curve.length - 1, index))];
  const meets = p.p95 <= t.traffic.sloP95 && p.err <= t.traffic.errorBudget;
  return `At ${n0(p.rps)} requests a second: p95 ${n0(p.p95)} ms, p99 ${n0(p.p99)} ms, ${pct1(p.err)} errors, and the busiest component ${pct(p.maxRho)} utilized. That ${meets ? "meets" : "misses"} the goal.`;
}

/** The curve point nearest the traffic the template ships with. */
export const nearestCurveIndex = (t: ExampleTemplate) => {
  let best = 0;
  t.limits.curve.forEach((p, i) => {
    if (Math.abs(p.rps - t.traffic.rps) < Math.abs(t.limits.curve[best].rps - t.traffic.rps)) best = i;
  });
  return best;
};

export const BEHAVIOR_WORD: Record<CatalogComponent["behavior"], string> = {
  none: "has no limit of its own",
  shed: "drops the requests it cannot serve",
  backlog: "builds up a backlog of waiting work",
  timeout: "makes requests wait until they time out",
  reject: "turns away what does not fit",
};

export const SETTING_LABEL: Record<string, string> = {
  capacity: "capacity",
  replicas: "replicas",
  latency: "service time",
  region: "region",
  hitRatio: "hit ratio",
  share: "share of traffic",
  maxDepth: "queue size limit",
};

export const capacityText = (c: CatalogComponent) => (c.capacity.kind === "finite" ? `${n0(c.capacity.value)} requests a second per replica` : "no limit (it only creates traffic)");
export function defaultsText(c: CatalogComponent): string {
  const d = c.defaults;
  const parts = [`${d.replicas} replica`];
  if (d.hitRatio !== undefined) parts.push(`hit ratio ${pct(d.hitRatio)}`);
  if (d.share !== undefined) parts.push(`${pct(d.share)} of traffic`);
  if (d.maxDepth !== undefined) parts.push(`queue limit ${n0(d.maxDepth)}`);
  return parts.join(", ");
}

/** Components grouped by category, in the order the catalog lists them. */
export function byCategory(components: CatalogComponent[] = CATALOG.components): Array<[string, CatalogComponent[]]> {
  const groups = new Map<string, CatalogComponent[]>();
  for (const c of components) groups.set(c.category, [...(groups.get(c.category) ?? []), c]);
  return [...groups.entries()];
}

export const presetText = (p: Preset) => `${n0(p.traffic.rps)} requests a second, bursts ×${p.traffic.burst}, ${pct(p.traffic.readRatio)} reads, p95 goal ${n0(p.traffic.sloP95)} ms, ${p.traffic.shape} shape`;

/** Where "make your own copy" leads: signed-in people go straight to the template; guests sign up first and come back. */
export const startPath = (id: string) => `/new/template?template=${encodeURIComponent(id)}`;
